insert into public.services (slug, name, title, description, hero_image, features, types, tips, sort_order) values ('blouse-stitching', 'Blouses', 'Blouse stitching in Chennai', 'A saree is only as good as the blouse under it. We cut every blouse to your measurements, line it properly and fit it on you, so it sits flat at the back, holds at the shoulder and still lets you lift your arms.
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Simple blouse', '₹980', 1 from public.services where slug = 'blouse-stitching';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Lined blouse', '₹1280', 2 from public.services where slug = 'blouse-stitching';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Padded blouse', '₹1580', 3 from public.services where slug = 'blouse-stitching';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Bridal maggam work', 'From ₹3500', 4 from public.services where slug = 'blouse-stitching';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'Do you supply the lining?', 'Yes. We can supply lining in a matching shade, or use your own. Tell us at the fitting.', 1 from public.services where slug = 'blouse-stitching';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'Can you copy a design from a photo?', 'Yes. Send the photo on WhatsApp. If your fabric cannot hold that design, we will tell you before we cut.', 2 from public.services where slug = 'blouse-stitching';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'Can you stitch from a blouse that already fits me?', 'Yes. Bring a blouse that fits you well. We take measurements from it as well as from you.', 3 from public.services where slug = 'blouse-stitching';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'How long does a bridal blouse take?', 'It depends on the embroidery. We agree the delivery date with you before we start. For a wedding, book a few weeks ahead.', 4 from public.services where slug = 'blouse-stitching';
insert into public.services (slug, name, title, description, hero_image, features, types, tips, sort_order) values ('lehenga-choli', 'Lehengas', 'Lehenga stitching in Chennai', 'A lehenga has to look right when you stand still and when you dance. We set the flare, the waistband and the length to your measurements and your heels, then fit it on you before we finish the hem.
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Lehenga stitching', '₹2500', 1 from public.services where slug = 'lehenga-choli';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Kali lehenga', '₹3500', 2 from public.services where slug = 'lehenga-choli';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Designer lehenga', '₹4500', 3 from public.services where slug = 'lehenga-choli';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Bridal lehenga', '₹8500', 4 from public.services where slug = 'lehenga-choli';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'How much does lehenga stitching cost?', 'See the starting prices on this page. The final price depends on the cut, the lining and any work, and we confirm it before we start.', 1 from public.services where slug = 'lehenga-choli';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'How long does a lehenga take?', 'We agree the date with you before we start. For a wedding, book early, especially in the wedding season.', 2 from public.services where slug = 'lehenga-choli';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'What is the difference between kali and umbrella cut?', 'A kali lehenga is made of many tapered panels and holds a heavy border well. An umbrella cut is one circle of fabric and swings more softly.', 3 from public.services where slug = 'lehenga-choli';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'How much fabric do I need?', 'It depends on the cut and your height. Send us a photo of the fabric and its length on WhatsApp and we will tell you.', 4 from public.services where slug = 'lehenga-choli';
insert into public.services (slug, name, title, description, hero_image, features, types, tips, sort_order) values ('anarkali', 'Anarkalis', 'Anarkali stitching in Chennai', 'An anarkali is all about the flare: how it falls when you stand and how it moves when you walk. We work out the panels for your height and your fabric, and fit the bodice on you before the skirt is joined.
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Simple anarkali', '₹2200', 1 from public.services where slug = 'anarkali';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Kalidar anarkali', '₹2800', 2 from public.services where slug = 'anarkali';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Party gown', '₹3500', 3 from public.services where slug = 'anarkali';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Bridal anarkali', '₹5500', 4 from public.services where slug = 'anarkali';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'Can you make an anarkali from a saree?', 'Often, yes. It depends on the length of the saree and where the border falls. Bring it and we will tell you what is possible.', 1 from public.services where slug = 'anarkali';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'Do you add can-can?', 'Yes, if you want more volume. We can show you the difference at the fitting.', 2 from public.services where slug = 'anarkali';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'How much fabric do I need for a full flare?', 'It depends on your height and the number of panels. Send us a photo of the fabric and its length on WhatsApp.', 3 from public.services where slug = 'anarkali';
insert into public.services (slug, name, title, description, hero_image, features, types, tips, sort_order) values ('kids-frock', 'Girls’ wear', 'Frocks and festive wear for girls', 'Children grow fast and never sit still, so we stitch for both. Soft lining wherever the fabric touches skin, no scratchy work at the neck or underarms, and extra margin inside the seams so the dress can be let out later.
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Simple frock', '₹650', 1 from public.services where slug = 'kids-frock';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Party frock', '₹1200', 2 from public.services where slug = 'kids-frock';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Pattu pavadai or lehenga set', '₹1500', 3 from public.services where slug = 'kids-frock';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'School uniform', '₹450', 4 from public.services where slug = 'kids-frock';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'Do you stitch matching mother and daughter outfits?', 'Yes. Bring enough fabric for both and we will stitch them as a set.', 1 from public.services where slug = 'kids-frock';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'Which fabrics are best for sensitive skin?', 'Cotton and soft linings are the gentlest. For silk or net, we line every part that touches the skin.', 2 from public.services where slug = 'kids-frock';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'Can you stitch a costume for a school function?', 'Tell us what you need and the date on WhatsApp. If we can do it well in that time, we will say yes.', 3 from public.services where slug = 'kids-frock';
insert into public.services (slug, name, title, description, hero_image, features, types, tips, sort_order) values ('kurti', 'Kurtis', 'Kurti stitching for daily and office wear', 'A readymade kurti fits nobody exactly: the shoulder slips, the armhole pulls, or the length is wrong. We stitch kurtis to your measurements, so the clothes you wear most often are the ones that fit best.
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Simple cotton kurti', '₹450', 1 from public.services where slug = 'kurti';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Lined kurti', '₹650', 2 from public.services where slug = 'kurti';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Designer kurti', '₹950', 3 from public.services where slug = 'kurti';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Kurti with pants', '₹950', 4 from public.services where slug = 'kurti';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'Can you add pockets?', 'Yes, in the side seams of the kurti or in the pants. Ask at the fitting.', 1 from public.services where slug = 'kurti';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'Do you alter readymade kurtis?', 'Yes. We can change the length, take in the sides, shorten the sleeves or fix the shoulders.', 2 from public.services where slug = 'kurti';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'Can I give several kurtis at once?', 'Yes. Bring all the fabrics together and we will agree one delivery date for the whole set.', 3 from public.services where slug = 'kurti';
insert into public.services (slug, name, title, description, hero_image, features, types, tips, sort_order) values ('suit-pant', 'Pant suits', 'Pant suits and trousers for women', 'A suit has nowhere to hide a poor fit. We cut the trousers for your waist, your hips and the shoes you will wear, and shape the blazer to your shoulders, so it looks sharp without feeling tight.
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Trousers', '₹650', 1 from public.services where slug = 'suit-pant';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Waistcoat', '₹1200', 2 from public.services where slug = 'suit-pant';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Blazer, unlined', '₹1800', 3 from public.services where slug = 'suit-pant';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Full suit', '₹2800', 4 from public.services where slug = 'suit-pant';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'Do you stitch blazers for women?', 'Yes, lined or unlined. See the starting prices on this page.', 1 from public.services where slug = 'suit-pant';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'How do you set the trouser length?', 'With the shoes you plan to wear. Bring them to the fitting.', 2 from public.services where slug = 'suit-pant';
insert into public.faqs (service_id, question, answer, sort_order) select id, 'Do white trousers need lining?', 'Usually yes, so they are not see-through. We will check your fabric against the light.', 3 from public.services where slug = 'suit-pant';
insert into public.faqs (service_id, question, answer, sort_order) values (null, 'How do I book?', 'Send a request from the booking page, or message us on WhatsApp. We reply to agree a time for measurements.', 1);
insert into public.faqs (service_id, question, answer, sort_order) values (null, 'What should I bring?', 'Your fabric, a photo of the design you like, and a piece of clothing that already fits you well if you have one. For long outfits, bring the shoes you will wear.', 2);
insert into public.faqs (service_id, question, answer, sort_order) values (null, 'Will it fit?', 'We fit every outfit on you before it is finished and adjust it until it sits right. If something still needs a change after delivery, tell us.', 3);
insert into public.faqs (service_id, question, answer, sort_order) values (null, 'When will it be ready?', 'We agree the delivery date with you before we start stitching. For weddings and festivals, book early.', 4);
insert into public.faqs (service_id, question, answer, sort_order) values (null, 'How much will it cost, and how do I pay?', 'Starting prices are on the prices page. We confirm the final price before we start. There is no online payment: you pay in person, by UPI or on delivery.', 5);
insert into public.faqs (service_id, question, answer, sort_order) values (null, 'Which areas do you cover?', 'Chennai for now. Message us on WhatsApp to check your area.', 6);
